def vigenere_decrypt(key: str, ciphertext: str) -> str:
    """
    Decrypts a ciphertext encrypted with the Vigenère cipher using the provided key.

    Args:
        key (str): The encryption key used to encrypt the original plaintext.
               This key should consist only of alphabetic characters.
        ciphertext (str): The encrypted text that needs to be decrypted.
                      The ciphertext should consist only of alphabetic characters.

    Returns:
        str: The decrypted plaintext corresponding to the input ciphertext.
    """
    def vigenere_cipher(char: str, shift: int) -> str:
        # This function implements a simple Caesar cipher with a shift of 'shift'
        if char.isalpha():
            if char.islower():
                return chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            else:
                return chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
        else:
            return char

    # Convert the key to lowercase and remove any non-alphabetic characters
    key = key.lower().replace(' ', '').strip()
    # Calculate the number of letters in the key
    key_length = len(key)

    # Initialize the decrypted plaintext and the current shift value
    plaintext = ""
    current_shift = 0

    # Iterate through the ciphertext, taking one letter at a time
    for char in ciphertext:
        if char.isalpha():
            # If the letter is not a space, shift it using the current shift value
            if char.islower():
                plaintext += chr((ord(char) - ord('a') + current_shift) % 26 + ord('a'))
            else:
                plaintext += chr((ord(char) - ord('A') + current_shift) % 26 + ord('A'))
            # Increment the shift value by the length of the key if at the end of a keyword
            if current_shift >= key_length - 1:
                current_shift = 0
            else:
                current_shift += 1
        else:
            # If the letter is a space, add it to the plaintext as is
            plaintext += char

    return plaintext
